def event_files_page(frame):
    st.header("Documenti e fotografie evento")
    records, record_ids = event_options(frame)
    if not record_ids:
        st.info("Crea prima un evento.")
        return
    event_id = st.selectbox("Evento", record_ids, format_func=lambda item_id: event_label(records[item_id]))
    vehicle_document_tables()
    with db() as conn:
        event_plates = sorted({row[0] for row in conn.execute('SELECT plate FROM event_vehicles WHERE event_id=?', (event_id,)) if row[0]})
    asset_plate = st.selectbox('Associa allegati alla targa (facoltativo)', [''] + event_plates,
                               format_func=lambda value:value or 'Documenti generali dell’evento', key='event_asset_plate_'+event_id)
    uploads = st.file_uploader("Carica documenti o fotografie", accept_multiple_files=True, key=f"event_upload_{event_id}")
    if st.button("Archivia allegati", type="primary", disabled=not uploads, use_container_width=True):
        rows = [(str(uuid.uuid4()), event_id, clean(file.name), clean(file.type), sqlite3.Binary(file.getvalue()), datetime.now().isoformat(timespec="seconds")) for file in uploads if file.getvalue()]
        with db() as conn:
            conn.executemany("INSERT INTO event_files VALUES (?, ?, ?, ?, ?, ?)", rows)
            if asset_plate:
                conn.executemany('INSERT INTO event_file_plates VALUES (?,?)', [(row[0], re.sub(r'[^A-Z0-9]', '', upper(asset_plate))) for row in rows])
        st.success(f"Allegati archiviati: {len(rows)}.")
        st.rerun()
    with db() as conn:
        files = [dict(row) for row in conn.execute("SELECT * FROM event_files WHERE event_id = ? ORDER BY created_at DESC", (event_id,)).fetchall()]
    if not files:
        st.info("Nessun allegato presente.")
        return
    for file in files:
        c1, c2, c3 = st.columns([4, 1, 1])
        c1.write(file["file_name"])
        c2.download_button("Scarica", file["file_data"], file["file_name"], mime=file["mime_type"] or "application/octet-stream", key=f"event_download_{file['id']}")
        if c3.button("Elimina", key=f"event_delete_{file['id']}"):
            with db() as conn:
                conn.execute("DELETE FROM event_files WHERE id = ?", (file["id"],))
            st.rerun()


def event_vehicles_page(frame):
    vehicle_tables()
    st.header("Veicoli assegnati all’evento")
    st.caption(
        "Inserisci o incolla l’elenco direttamente nella tabella. Le righe vengono ordinate per gruppo, "
        "targa, marca e modello. Approntamento e ritiro sono due stati distinti."
    )
    records, record_ids = event_options(frame)
    if not record_ids:
        st.info("Crea prima un evento.")
        return
    event_id = st.selectbox(
        "Evento",
        record_ids,
        format_func=lambda item_id: event_label(records[item_id]),
        key="event_vehicle_event",
    )
    assignment_message = st.session_state.pop('event_archive_message', None)
    if assignment_message:
        st.success(assignment_message)
    event_assignment_panel(st, db, event_id, current_user)
    with db() as conn:
        stored = [
            dict(row) for row in conn.execute(
                """
                SELECT * FROM event_vehicles
                WHERE event_id = ?
                ORDER BY UPPER(COALESCE(vehicle_group, '')), UPPER(COALESCE(plate, '')),
                         UPPER(COALESCE(brand, '')), UPPER(COALESCE(model, ''))
                """,
                (event_id,),
            ).fetchall()
        ]
    vehicle_tables()
    with db() as conn:
        checks = pd.read_sql_query('SELECT id, plate, payload, checked_at FROM vehicle_checks ORDER BY checked_at DESC, created_at DESC', conn)
    linked_checks = [(row, json.loads(row.payload)) for row in checks.itertuples()
                     if json.loads(row.payload).get('event_id') == event_id]
    with st.expander(f"Check-in vetture dell’evento ({len(linked_checks)})"):
        if not linked_checks:
            st.info('Nessun check-in collegato. Seleziona questo evento in VETTURE → Inserimento rapido vettura.')
        else:
            options = {row.id: (row, payload) for row, payload in linked_checks}
            selected_check = st.selectbox('Scheda check-in', list(options),
                format_func=lambda value: f"{options[value][0].plate} · {options[value][0].checked_at}", key=f'event_check_{event_id}')
            row, payload = options[selected_check]
            st.write(vehicle_preparation(payload))
            prep_options = ['Da completare', 'Da verificare', 'Pronta']
            previous_prep = payload.get('preparation_status', 'Pronta' if vehicle_ready(payload) else 'Da verificare')
            chosen_prep = st.selectbox('Approntamento — scelta operatore', prep_options,
                                      index=prep_options.index(previous_prep), key=f'prep_{selected_check}')
            quick_park = st.text_input('Park N°', value=payload.get('park_number', ''), key=f'park_{selected_check}')
            quick_inside = st.selectbox('Pulizia interna', CLEANING_OPTIONS, index=CLEANING_OPTIONS.index(payload.get('cleaning_inside', 'Da verificare')), key=f'inside_{selected_check}')
            quick_outside = st.selectbox('Pulizia esterna', CLEANING_OPTIONS, index=CLEANING_OPTIONS.index(payload.get('cleaning_outside', 'Da verificare')), key=f'outside_{selected_check}')
            quick_maintenance = st.selectbox('Manutenzione', MAINTENANCE_OPTIONS, index=MAINTENANCE_OPTIONS.index(payload.get('maintenance', 'Da verificare')), key=f'maintenance_{selected_check}')
            quick_repairs = st.text_area('Riparazioni / lavori da eseguire', value=payload.get('repair_tasks', ''), key=f'repairs_{selected_check}')
            quick_notes = st.text_area('Note manutenzione / pulizia', value=payload.get('maintenance_notes', ''), key=f'maintnotes_{selected_check}')
            if st.button('Salva approntamento, pulizia e manutenzione', key=f'prep_save_{selected_check}'):
                payload.update(repair_tasks=quick_repairs, park_number=quick_park, cleaning_inside=quick_inside, cleaning_outside=quick_outside, maintenance=quick_maintenance, maintenance_notes=quick_notes)
                payload['preparation_status'] = chosen_prep
                payload['preparation_operator'] = current_operator() or current_user().get('display_name', '')
                save_vehicle_check(payload, [], selected_check)
                st.session_state['vehicle_saved_message'] = vehicle_notify(selected_check, payload)
                st.rerun()
            vehicle_print_buttons(payload, selected_check, 'event_'+selected_check)
            st.write(f"Operatore: {payload.get('operator', '')} — Km: {payload.get('km', '')}")
            st.dataframe(vehicle_accessory_style(pd.DataFrame([{'Voce': item.get('Voce', ''), 'Stato': vehicle_item_status(item)} for item in payload.get('checklist', [])])), hide_index=True, use_container_width=True)
            st.dataframe(pd.DataFrame(payload.get('tires', [])), hide_index=True, use_container_width=True)
            st.write(f"Danni: {payload.get('damage_status', 'Da verificare')} — {payload.get('damage_notes', '')}")
            with db() as conn:
                conn.row_factory = sqlite3.Row
                photos = [dict(photo) for photo in conn.execute('SELECT * FROM vehicle_check_photos WHERE check_id=?', (selected_check,))]
            for photo in photos:
                st.image(photo['file_data'], caption=photo['file_name'], width=250)
            st.caption('Per modificare la scheda, apri VETTURE → Archivio vetture e seleziona questa targa.')
    st.subheader("Inserimento o modifica veicolo")
    vehicle_by_id = {item["id"]: item for item in stored}
    selected_vehicle_id = st.selectbox(
        "Veicolo da modificare",
        [""] + list(vehicle_by_id),
        format_func=lambda item_id: "➕ NUOVO VEICOLO" if not item_id else " | ".join(
            value for value in [
                upper(vehicle_by_id[item_id].get("plate")),
                clean(vehicle_by_id[item_id].get("brand")),
                clean(vehicle_by_id[item_id].get("model")),
                clean(vehicle_by_id[item_id].get("assigned_to")),
            ] if value
        ),
        key=f"event_vehicle_selector_{event_id}",
    )
    selected_vehicle = vehicle_by_id.get(selected_vehicle_id, {})
    form_key = selected_vehicle_id or "new"
    existing_pickup = clean(selected_vehicle.get("pickup_date"))
    pickup_default = date.today()
    if existing_pickup:
        parsed_pickup = pd.to_datetime(existing_pickup, errors="coerce", dayfirst=True)
        if pd.notna(parsed_pickup):
            pickup_default = parsed_pickup.date()
    with st.form(f"event_vehicle_form_{event_id}_{form_key}", clear_on_submit=not bool(selected_vehicle_id)):
        c1, c2, c3, c4 = st.columns(4)
        vehicle_group = c1.text_input("Gruppo", value=clean(selected_vehicle.get("vehicle_group")))
        plate = c2.text_input("Targa *", value=upper(selected_vehicle.get("plate")))
        brand = c3.text_input("Marca", value=clean(selected_vehicle.get("brand")))
        model = c4.text_input("Modello", value=clean(selected_vehicle.get("model")))
        c5, c6, c7 = st.columns(3)
        assigned_to = c5.text_input("Assegnata a", value=clean(selected_vehicle.get("assigned_to")))
        ra = c6.text_input("RA", value=upper(selected_vehicle.get("ra")))
        picked_up = c7.checkbox("Veicolo ritirato", value=bool(existing_pickup))
        c8, c9 = st.columns([1, 2])
        pickup_date = c8.date_input("Data ritiro", value=pickup_default, disabled=not picked_up)
        park_number = st.text_input("Park N°", value=clean(selected_vehicle.get("park_number")), key=f"event_park_{event_id}_{form_key}")
        vehicle_notes = c9.text_input("Note", value=clean(selected_vehicle.get("notes")))
        save_vehicle = st.form_submit_button(
            "Aggiorna veicolo" if selected_vehicle_id else "Aggiungi veicolo alla tabella",
            type="primary", use_container_width=True,
        )
    if save_vehicle:
        if not clean(plate):
            st.error("Inserisci almeno la targa del veicolo.")
        else:
            vehicle_id = selected_vehicle_id or str(uuid.uuid4())
            with db() as conn:
                conn.execute(
                    """
                    INSERT INTO event_vehicles
                    (id,event_id,vehicle_group,plate,brand,model,assigned_to,ra,pickup_date,notes,updated_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(id) DO UPDATE SET
                        vehicle_group=excluded.vehicle_group,plate=excluded.plate,brand=excluded.brand,
                        model=excluded.model,assigned_to=excluded.assigned_to,ra=excluded.ra,
                        pickup_date=excluded.pickup_date,notes=excluded.notes,updated_at=excluded.updated_at
                    """,
                    (
                        vehicle_id, event_id, clean(vehicle_group), upper(plate), clean(brand), clean(model),
                        clean(assigned_to), upper(ra), pickup_date.isoformat() if picked_up else "",
                        clean(vehicle_notes), datetime.now().isoformat(timespec="seconds"),
                    ),
                )
                conn.execute("UPDATE event_vehicles SET park_number=? WHERE id=?", (clean(park_number), vehicle_id))
            st.success("Veicolo aggiornato nella tabella." if selected_vehicle_id else "Veicolo aggiunto automaticamente alla tabella.")
            st.rerun()
    if selected_vehicle_id:
        confirm_vehicle_delete = st.checkbox(
            "Confermo l’eliminazione del veicolo selezionato",
            key=f"confirm_vehicle_delete_{event_id}_{selected_vehicle_id}",
        )
        if st.button(
            "Elimina veicolo selezionato", disabled=not confirm_vehicle_delete,
            key=f"delete_vehicle_{event_id}_{selected_vehicle_id}", use_container_width=True,
        ):
            with db() as conn:
                conn.execute("DELETE FROM event_vehicles WHERE id = ? AND event_id = ?", (selected_vehicle_id, event_id))
            st.success("Veicolo eliminato.")
            st.rerun()
    st.divider()
    st.subheader("Elenco veicoli dell’evento")
    columns = ["_id", "Approntamento", "Gruppo", "Targa", "Marca", "Modello", "Assegnata a", "RA", "Data ritiro", "Stato", "Park N°", "Pulizia interna", "Pulizia esterna", "Manutenzione", "Note"]
    latest_checks = {}
    for check, payload in linked_checks:
        normalized_plate = re.sub(r"[^A-Z0-9]", "", upper(check.plate))
        latest_checks.setdefault(normalized_plate, payload)
    rows = []
    for item in stored:
        pickup = clean(item.get("pickup_date"))
        check_payload = latest_checks.get(re.sub(r"[^A-Z0-9]", "", upper(item.get("plate"))), {})
        rows.append({
            "_id": item["id"], "Approntamento": vehicle_preparation(latest_checks[re.sub(r"[^A-Z0-9]", "", upper(item.get("plate")))]) if re.sub(r"[^A-Z0-9]", "", upper(item.get("plate"))) in latest_checks else "🔴 Da completare",
            "Stato": "🟢" if pickup else "🔴",
            "Gruppo": item.get("vehicle_group", ""), "Targa": item.get("plate", ""),
            "Marca": item.get("brand", ""), "Modello": item.get("model", ""),
            "Assegnata a": item.get("assigned_to", ""), "RA": item.get("ra", ""),
            "Data ritiro": pickup, "Park N°": item.get("park_number", ""),
            "Pulizia interna": vehicle_service_label(check_payload.get("cleaning_inside")),
            "Pulizia esterna": vehicle_service_label(check_payload.get("cleaning_outside")),
            "Manutenzione": vehicle_service_label(check_payload.get("maintenance"), maintenance=True),
            "Note": item.get("notes", ""),
        })
    vehicle_summary_exports(stored, latest_checks, str(records[event_id].title), event_id)
    source = pd.DataFrame(rows, columns=columns)
    if source.empty:
        source = pd.DataFrame(columns=columns)
    total = len(stored)
    collected = sum(bool(clean(item.get("pickup_date"))) for item in stored)
    m1, m2, m3 = st.columns(3)
    m1.metric("Veicoli assegnati", total, delta=f"su 40 previsti" if total <= 40 else "oltre 40 previsti")
    m2.metric("Ritirati", collected)
    m3.metric("Da ritirare", max(total - collected, 0))
    edited = st.data_editor(
        source,
        num_rows="dynamic",
        use_container_width=True,
        hide_index=True,
        key=f"event_vehicle_editor_{event_id}",
        column_config={
            "_id": None,
            "Approntamento": st.column_config.TextColumn("Approntamento", disabled=True, width="medium"),
            "Stato": st.column_config.TextColumn("Ritiro", disabled=True, width="small", help="🟢 ritirata; 🔴 non ancora ritirata"),
            "Gruppo": st.column_config.TextColumn("Gruppo", width="medium"),
            "Targa": st.column_config.TextColumn("Targa", width="small"),
            "Marca": st.column_config.TextColumn("Marca", width="medium"),
            "Modello": st.column_config.TextColumn("Modello", width="medium"),
            "Assegnata a": st.column_config.TextColumn("Assegnata a", width="medium"),
            "RA": st.column_config.TextColumn("RA", width="small"),
            "Data ritiro": st.column_config.TextColumn("Data ritiro", help="Esempio: 25/09/2026", width="small"),
            "Park N°": st.column_config.TextColumn("Park N°", width="small"),
            "Note": st.column_config.TextColumn("Note", width="large"),
        },
        disabled=["Approntamento", "Stato", "Pulizia interna", "Pulizia esterna", "Manutenzione"],
    )
    st.caption("Puoi copiare più righe da Excel e incollarle nella prima cella. Usa il + in fondo per aggiungere una riga.")
    export = edited.copy()
    if "_id" in export.columns:
        export = export.drop(columns=["_id"])
    export["Stato"] = export.get("Data ritiro", pd.Series(dtype=str)).fillna("").astype(str).str.strip().map(
        lambda value: "RITIRATA" if value else "DA RITIRARE"
    )
    export = export.sort_values(
        ["Gruppo", "Targa", "Marca", "Modello"],
        key=lambda column: column.fillna("").astype(str).str.upper(),
    )
    safe_event_name = re.sub(r"[^A-Za-z0-9_-]+", "_", str(records[event_id].title)).strip("_") or "evento"
    d1, d2 = st.columns(2)
    d1.download_button(
        "Scarica elenco in Excel", table_to_excel(export, "Veicoli evento"),
        f"veicoli_{safe_event_name}.xlsx", use_container_width=True,
    )
    d2.download_button(
        "Scarica elenco in PDF", event_vehicles_to_pdf(export, str(records[event_id].title)),
        f"veicoli_{safe_event_name}.pdf", mime="application/pdf", use_container_width=True,
    )
    if st.button("Salva elenco veicoli", type="primary", use_container_width=True):
        saved_ids = []
        now = datetime.now().isoformat(timespec="seconds")
        with db() as conn:
            for _, row in edited.fillna("").iterrows():
                values = {name: clean(row.get(name, "")) for name in ["Gruppo", "Targa", "Marca", "Modello", "Assegnata a", "RA", "Data ritiro", "Park N°", "Note"]}
                if not any(values.values()):
                    continue
                vehicle_id = clean(row.get("_id")) or str(uuid.uuid4())
                saved_ids.append(vehicle_id)
                conn.execute(
                    """
                    INSERT INTO event_vehicles
                    (id,event_id,vehicle_group,plate,brand,model,assigned_to,ra,pickup_date,notes,updated_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(id) DO UPDATE SET
                        vehicle_group=excluded.vehicle_group,plate=excluded.plate,brand=excluded.brand,
                        model=excluded.model,assigned_to=excluded.assigned_to,ra=excluded.ra,
                        pickup_date=excluded.pickup_date,notes=excluded.notes,updated_at=excluded.updated_at
                    """,
                    (vehicle_id, event_id, values["Gruppo"], upper(values["Targa"]), values["Marca"],
                     values["Modello"], values["Assegnata a"], upper(values["RA"]),
                     values["Data ritiro"], values["Note"], now),
                )
                conn.execute("UPDATE event_vehicles SET park_number=? WHERE id=?", (values["Park N°"], vehicle_id))
            if saved_ids:
                placeholders = ",".join("?" for _ in saved_ids)
                conn.execute(
                    f"DELETE FROM event_vehicles WHERE event_id = ? AND id NOT IN ({placeholders})",
                    [event_id] + saved_ids,
                )
            else:
                conn.execute("DELETE FROM event_vehicles WHERE event_id = ?", (event_id,))
        st.success(f"Elenco salvato: {len(saved_ids)} veicoli.")
        st.rerun()


def _safe_excel_text(value):
    if pd.isna(value):
        return ""
    return str(value).strip()


def import_vehicle_recovery_excel(file_bytes, event_id=""):
    frame = pd.read_excel(io.BytesIO(file_bytes), sheet_name=0, dtype=object)
    required = {"Targa", "Marca", "Modello", "Gruppo", "Check-in", "Data controllo", "Operatore"}
    missing_columns = sorted(required - set(frame.columns))
    if missing_columns:
        raise ValueError("Colonne mancanti: " + ", ".join(missing_columns))
    vehicle_tables()
    event_title = ""
    if event_id:
        with db() as connection:
            event = connection.execute("SELECT title FROM special_events WHERE id=?", (event_id,)).fetchone()
        if not event:
            raise ValueError("L'evento selezionato non esiste più.")
        event_title = event[0]
    imported = 0
    skipped = 0
    now = datetime.now().isoformat(timespec="seconds")
    with db() as connection:
        for _, row in frame.iterrows():
            plate = re.sub(r"[^A-Z0-9]", "", upper(_safe_excel_text(row.get("Targa"))))
            if not plate:
                skipped += 1
                continue
            checked_raw = row.get("Data controllo")
            try:
                checked_at = pd.to_datetime(checked_raw).date().isoformat()
            except Exception:
                checked_at = date.today().isoformat()
            missing_items = {
                clean(item) for item in re.split(r"[;,]", _safe_excel_text(row.get("Documenti / dotazioni mancanti")))
                if clean(item)
            }
            checklist = []
            for label in VEHICLE_CHECKLIST:
                state = "Non presente" if label in missing_items else "Non previsto"
                checklist.append({"Voce": label, "Stato": state, "Presente": False, "Non previsto": state == "Non previsto"})
            tire_size = _safe_excel_text(row.get("Misura gomme se calze mancanti"))
            damage_status = _safe_excel_text(row.get("Danni")) or "Da verificare"
            payload = {
                "event_id": event_id, "event_title": event_title,
                "plate": plate, "brand": _safe_excel_text(row.get("Marca")),
                "model": _safe_excel_text(row.get("Modello")), "group": _safe_excel_text(row.get("Gruppo")),
                "park_number": _safe_excel_text(row.get("Park N°")), "ra": "", "km": 0, "fuel": 100,
                "operator": _safe_excel_text(row.get("Operatore")) or "SERGIO", "checked_at": checked_at,
                "preparation_status": _safe_excel_text(row.get("Approntamento")) or "Da completare",
                "preparation_operator": _safe_excel_text(row.get("Operatore")) or "SERGIO",
                "notes": "Recuperato dal riepilogo Excel dopo perdita del database.",
                "damage_status": damage_status, "damage_notes": _safe_excel_text(row.get("Descrizione danni")),
                "maintenance": _safe_excel_text(row.get("Manutenzione")) or "Da verificare",
                "repair_tasks": _safe_excel_text(row.get("Lavori da eseguire")),
                "maintenance_notes": _safe_excel_text(row.get("Note manutenzione")),
                "cleaning_inside": _safe_excel_text(row.get("Pulizia interna")) or "Da verificare",
                "cleaning_outside": _safe_excel_text(row.get("Pulizia esterna")) or "Da verificare",
                "tires_ok": False, "checklist": checklist,
                "tires": [{"Marca": "", "Modello": "", "Tipo": "", "Misura": tire_size, "Stato / note": "Da verificare"}],
            }
            existing = connection.execute(
                "SELECT id FROM vehicle_checks WHERE plate=? AND substr(checked_at,1,10)=? ORDER BY updated_at DESC LIMIT 1",
                (plate, checked_at),
            ).fetchone()
            identifier = existing[0] if existing else str(uuid.uuid4())
            encoded = json.dumps(payload, ensure_ascii=False)
            if existing:
                connection.execute(
                    "UPDATE vehicle_checks SET operator=?,payload=?,updated_at=? WHERE id=?",
                    (payload["operator"], encoded, now, identifier),
                )
            else:
                connection.execute(
                    "INSERT INTO vehicle_checks VALUES (?,?,?,?,?,?,?)",
                    (identifier, plate, checked_at, payload["operator"], encoded, now, now),
                )
            if event_id:
                event_vehicle = connection.execute(
                    "SELECT id FROM event_vehicles WHERE event_id=? AND replace(replace(upper(plate),' ',''),'-','')=?",
                    (event_id, plate),
                ).fetchone()
                if event_vehicle:
                    connection.execute(
                        "UPDATE event_vehicles SET vehicle_group=?,brand=?,model=?,park_number=?,updated_at=? WHERE id=?",
                        (payload["group"], payload["brand"], payload["model"], payload["park_number"], now, event_vehicle[0]),
                    )
                else:
                    connection.execute(
                        "INSERT INTO event_vehicles (id,event_id,vehicle_group,plate,brand,model,assigned_to,ra,pickup_date,notes,updated_at,park_number) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
                        (str(uuid.uuid4()), event_id, payload["group"], plate, payload["brand"], payload["model"], "", "", "", "Recuperato da Excel", now, payload["park_number"]),
                    )
            connection.execute(
                "INSERT INTO vehicle_check_history VALUES (?,?,?,?,?,?)",
                (str(uuid.uuid4()), identifier, "RECUPERO DA EXCEL", current_user().get("username", ""), now, encoded),
            )
            imported += 1
    return imported, skipped


def _excel_column_guess(columns, aliases):
    normalized = {re.sub(r"[^a-z0-9]", "", str(column).lower()): column for column in columns}
    for alias in aliases:
        key = re.sub(r"[^a-z0-9]", "", alias.lower())
        if key in normalized:
            return normalized[key]
    return "— Non importare —"


def import_vehicle_excel_general(frame, mapping, mode):
    """Importa anagrafiche vetture da un foglio Excel già validato e mappato."""
    vehicle_tables()
    created = updated = skipped = 0
    now = datetime.now().isoformat(timespec="seconds")
    configured = configured_operators()
    default_operator = configured[0]["name"] if configured else (current_user().get("operator_name") or current_user().get("display_name") or "AMMINISTRATORE")

    def value(row, field):
        column = mapping.get(field)
        return _safe_excel_text(row.get(column)) if column and column != "— Non importare —" else ""

    with db() as connection:
        for _, row in frame.iterrows():
            plate = re.sub(r"[^A-Z0-9]", "", upper(value(row, "plate")))
            if not plate:
                skipped += 1
                continue
            existing = connection.execute(
                "SELECT id,payload FROM vehicle_checks WHERE plate=? ORDER BY checked_at DESC,updated_at DESC LIMIT 1",
                (plate,),
            ).fetchone()
            if existing and mode == "Crea solo targhe nuove":
                skipped += 1
                continue
            checked_text = value(row, "checked_at")
            parsed_date = pd.to_datetime(checked_text, errors="coerce", dayfirst=True)
            checked_at = parsed_date.date().isoformat() if pd.notna(parsed_date) else date.today().isoformat()
            if existing and mode == "Aggiorna la scheda più recente":
                identifier = existing["id"]
                payload = json.loads(existing["payload"])
                action = "AGGIORNAMENTO DA EXCEL"
            else:
                identifier = str(uuid.uuid4())
                payload = {
                    "event_id": "", "event_title": "", "plate": plate, "brand": "", "model": "",
                    "group": "", "park_number": "", "ra": "", "km": 0, "fuel": 100,
                    "operator": default_operator, "checked_at": checked_at,
                    "preparation_status": "Da completare", "preparation_operator": default_operator,
                    "notes": "Importato da Excel.", "damage_status": "Da verificare", "damage_notes": "",
                    "maintenance": "Da verificare", "repair_tasks": "", "maintenance_notes": "",
                    "cleaning_inside": "Da verificare", "cleaning_outside": "Da verificare",
                    "tires_ok": False,
                    "checklist": [{"Voce": label, "Stato": "Non previsto", "Presente": False, "Non previsto": True} for label in VEHICLE_CHECKLIST],
                    "tires": [{"Marca": "", "Modello": "", "Tipo": "", "Misura": "", "Stato / note": "Da verificare"}],
                }
                action = "IMPORTAZIONE DA EXCEL"
            text_fields = {"brand": "brand", "model": "model", "group": "group", "park_number": "park_number", "ra": "ra", "operator": "operator", "notes": "notes"}
            for field, payload_key in text_fields.items():
                incoming = value(row, field)
                if incoming:
                    payload[payload_key] = upper(incoming) if field in {"ra", "operator"} else incoming
            for field, default in (("km", payload.get("km", 0)), ("fuel", payload.get("fuel", 100))):
                incoming = value(row, field).replace(",", ".")
                if incoming:
                    try:
                        payload[field] = float(incoming)
                    except ValueError:
                        payload[field] = default
            payload["plate"] = plate
            payload["checked_at"] = checked_at
            payload["operator"] = payload.get("operator") or default_operator
            payload["preparation_operator"] = payload.get("preparation_operator") or payload["operator"]
            encoded = json.dumps(payload, ensure_ascii=False)
            if existing and mode == "Aggiorna la scheda più recente":
                connection.execute(
                    "UPDATE vehicle_checks SET checked_at=?,operator=?,payload=?,updated_at=? WHERE id=?",
                    (checked_at, payload["operator"], encoded, now, identifier),
                )
                updated += 1
            else:
                connection.execute(
                    "INSERT INTO vehicle_checks VALUES (?,?,?,?,?,?,?)",
                    (identifier, plate, checked_at, payload["operator"], encoded, now, now),
                )
                created += 1
            connection.execute(
                "INSERT INTO vehicle_check_history VALUES (?,?,?,?,?,?)",
                (str(uuid.uuid4()), identifier, action, current_user().get("username", ""), now, encoded),
            )
    return created, updated, skipped


def _restore_uploaded_database(uploaded):
    handle, temporary_name = tempfile.mkstemp(prefix="ancillary_manual_restore_", suffix=".db")
    os.close(handle)
    temporary = Path(temporary_name)
    try:
        temporary.write_bytes(uploaded.getvalue())
        if not _valid_database(temporary):
            raise ValueError("Il file non è un database Ancillary valido o è danneggiato.")
        safety = _database_snapshot()
        try:
            if safety:
                shutil.copy2(safety, APP_DIR / f"ancillary_prima_del_ripristino_{datetime.now().strftime('%Y%m%d_%H%M%S')}.db")
        finally:
            if safety:
                safety.unlink(missing_ok=True)
        shutil.copy2(temporary, DB_PATH)
        _upload_database_to_drive("ripristino manuale")
    finally:
        temporary.unlink(missing_ok=True)


def import_backup():
    st.header("Importazione e backup")
    st.subheader("Backup completo")
    if DB_PATH.exists():
        st.download_button("Scarica database", DB_PATH.read_bytes(), "ancillary_backup.db", mime="application/octet-stream", use_container_width=True)
    drive_status = st.session_state.get("drive_backup_status", PERSISTENCE_BOOT_STATUS.get("message", ""))
    st.info("Stato protezione Google Drive: " + str(drive_status))
    c_sync, c_restore = st.columns(2)
    if c_sync.button("Salva ora su Google Drive", use_container_width=True):
        if _upload_database_to_drive("backup manuale"):
            st.success("Database salvato su Google Drive.")
        else:
            st.error("Salvataggio Drive non riuscito. Controlla configurazione e stato mostrato sopra.")
    restore_upload = c_restore.file_uploader("Ripristina database (.db)", type=["db", "sqlite", "sqlite3"], key="manual_db_restore")
    confirm_restore = st.checkbox("Confermo di sostituire il database corrente con il file selezionato", key="confirm_manual_restore")
    if st.button("Ripristina database selezionato", disabled=restore_upload is None or not confirm_restore, use_container_width=True):
        try:
            _restore_uploaded_database(restore_upload)
        except (ValueError, OSError, sqlite3.Error) as exc:
            st.error(f"Ripristino non riuscito: {exc}")
        else:
            st.success("Database ripristinato e copiato su Google Drive.")
            st.cache_data.clear()
            st.rerun()
    st.caption("Il database viene salvato automaticamente su Google Drive dopo ogni modifica e in una copia giornaliera.")

    st.subheader("Recupero check-in vetture da Excel")
    st.caption("Importa il riepilogo recuperato senza reinserire manualmente targhe, danni, manutenzioni e dotazioni mancanti.")
    recovery_upload = st.file_uploader("File riepilogo vetture", type=["xlsx"], key="vehicle_recovery_excel")
    recovery_events = load_special_events()
    recovery_options = [""] + (recovery_events["id"].tolist() if not recovery_events.empty else [])
    recovery_event = st.selectbox(
        "Associa a un evento (facoltativo)", recovery_options,
        format_func=lambda value: "Nessun evento - archivio generale" if not value else event_label(recovery_events.loc[recovery_events["id"].eq(value)].iloc[0]),
        key="vehicle_recovery_event",
    )
    confirm_recovery = st.checkbox("Confermo l'importazione dei check-in recuperati", key="confirm_vehicle_recovery")
    if st.button("Importa check-in recuperati", disabled=recovery_upload is None or not confirm_recovery, use_container_width=True):
        try:
            imported, skipped = import_vehicle_recovery_excel(recovery_upload.getvalue(), recovery_event)
        except (ValueError, OSError, sqlite3.Error) as exc:
            st.error(f"Importazione non riuscita: {exc}")
        else:
            st.success(f"Check-in recuperati: {imported}. Righe escluse: {skipped}.")
            st.rerun()

    st.subheader("Importazione generale vetture da Excel")
    st.caption("Carica un Excel, controlla l’anteprima e associa le colonne. È obbligatoria soltanto la targa.")
    general_vehicle_upload = st.file_uploader("File Excel vetture", type=["xlsx"], key="general_vehicle_excel")
    if general_vehicle_upload is not None:
        try:
            general_frame = pd.read_excel(io.BytesIO(general_vehicle_upload.getvalue()), sheet_name=0, dtype=object)
        except Exception as exc:
            st.error(f"File Excel non leggibile: {exc}")
        else:
            general_frame = general_frame.dropna(how="all")
            st.write(f"Righe rilevate: **{len(general_frame)}**")
            st.dataframe(general_frame.head(20), hide_index=True, use_container_width=True)
            options = ["— Non importare —"] + [str(column) for column in general_frame.columns]
            definitions = [
                ("plate", "Targa *", ["Targa", "Plate"]), ("brand", "Marca", ["Marca", "Brand"]),
                ("model", "Modello", ["Modello", "Model"]), ("group", "Gruppo", ["Gruppo", "Group", "Categoria"]),
                ("park_number", "Park N°", ["Park N°", "Park", "Posto"]), ("ra", "RA", ["RA", "Contratto"]),
                ("checked_at", "Data controllo", ["Data controllo", "Data", "Check-in"]),
                ("operator", "Operatore", ["Operatore", "Operator"]), ("km", "Km", ["Km", "Chilometri"]),
                ("fuel", "Carburante / carica %", ["Carburante / carica %", "Carburante", "Fuel"]),
                ("notes", "Note", ["Note", "Annotazioni"]),
            ]
            mapping = {}
            columns_ui = st.columns(3)
            for index, (field, label, aliases) in enumerate(definitions):
                guessed = _excel_column_guess(general_frame.columns, aliases)
                mapping[field] = columns_ui[index % 3].selectbox(
                    label, options, index=options.index(guessed) if guessed in options else 0,
                    key=f"general_vehicle_map_{field}",
                )
            mode = st.radio(
                "Se la targa è già presente",
                ["Crea solo targhe nuove", "Aggiorna la scheda più recente", "Crea sempre una nuova scheda"],
                horizontal=True, key="general_vehicle_import_mode",
            )
            confirm_general = st.checkbox("Confermo l’importazione delle vetture mostrate in anteprima", key="confirm_general_vehicle_import")
            plate_ready = mapping.get("plate") != "— Non importare —"
            if not plate_ready:
                st.warning("Associa la colonna Targa per abilitare l’importazione.")
            if st.button(
                "Importa vetture da Excel", disabled=not (plate_ready and confirm_general and not general_frame.empty),
                type="primary", use_container_width=True,
            ):
                try:
                    created, updated, skipped = import_vehicle_excel_general(general_frame, mapping, mode)
                except (ValueError, OSError, sqlite3.Error) as exc:
                    st.error(f"Importazione non riuscita: {exc}")
                else:
                    st.success(f"Importazione completata: {created} create, {updated} aggiornate, {skipped} escluse.")
                    st.rerun()
    st.subheader("Importazione intelligente da Excel")
    st.caption("Il gestionale riconosce riepiloghi ancillary, report Contratti RA, Commissioni e Addebito Danni.")
    upload = st.file_uploader("Carica un file Excel", type=["xlsx"])
    if upload:
        file_bytes = upload.getvalue()
        detected = detect_excel_type(file_bytes)
        labels = {
            "ANCILLARY": "Riepilogo ancillary", "CONTRATTI_RA": "Analisi Contratti RA",
            "ADDEBITO_DANNI": "Riepilogo addebito danni", "COMMISSIONI": "Report Commissioni",
            "SCONOSCIUTO": "Formato non riconosciuto",
        }
        st.info(f"Formato rilevato: **{labels[detected]}**")
        if st.button("Importa, scorpora e analizza", type="primary", disabled=detected == "SCONOSCIUTO", use_container_width=True):
            if detected == "CONTRATTI_RA":
                added, main_sheet, period = import_contract_workbook(file_bytes, upload.name)
                st.success(f"Importati o aggiornati {added} contratti del periodo {period}. Foglio principale: {main_sheet}.")
                st.rerun()
            if detected == "COMMISSIONI":
                try:
                    added, periods = import_commission_workbook(file_bytes, upload.name)
                except (ValueError, KeyError, OSError) as exc:
                    st.error(f"Importazione Commissioni non riuscita: {exc}")
                else:
                    st.success(f"Importate o aggiornate {added} fatture Commissioni: {', '.join(periods)}.")
                    st.rerun()
                return
            if detected == "ADDEBITO_DANNI":
                added, skipped = import_damage_workbook(file_bytes, upload.name)
                st.success(f"Importate o aggiornate {added} segnalazioni danni.")
                if skipped:
                    st.info(f"Escluse {skipped} righe senza numero RA.")
                st.rerun()
            imported = pd.read_excel(io.BytesIO(file_bytes), sheet_name=0, dtype=object)
            added = 0
            skipped_before_start = 0
            for _, row in imported.iterrows():
                days = pd.to_numeric(row.get("GIORNI NOLEGGIO"), errors="coerce")
                cost = pd.to_numeric(row.get("COSTO TOTALE ANCILLARY (iva esclusa)"), errors="coerce")
                start = pd.to_datetime(row.get("DATA INIZIO NOLEGGIO"), errors="coerce")
                if pd.notna(start) and start.date() < ANCILLARY_START_DATE:
                    skipped_before_start += 1
                    continue
                vehicle = upper(row.get("TIPO DI VEICOLO"))
                ancillary = upper(row.get("SCELTA ANCILLARY (CAR)")) or upper(row.get("SCELTA ANCILLARY (VAN)"))
                save_record({
                    "ra": row.get("RA (Rental Agreement)"),
                    "start_date": "" if pd.isna(start) else start.date().isoformat(),
                    "rental_days": 0 if pd.isna(days) else int(days),
                    "source_raw": row.get("FONTE"), "operator": row.get("OPERATORE"),
                    "vehicle_type": vehicle, "ancillary": ancillary,
                    "ancillary_cost": None if pd.isna(cost) else float(cost),
                    "rental_type": row.get("TIPO NOLEGGIO"), "notes": "Importato da Excel",
                })
                added += 1
            st.success(f"Importati {added} record ancillary.")
            if skipped_before_start:
                st.info(f"Esclusi {skipped_before_start} record anteriori al 01/10/2026.")
            st.rerun()


def operator_settings():
    st.header("Configurazione operatori")
    st.caption("Gli operatori attivi compaiono nella tendina del modulo di inserimento. Lo storico non viene modificato.")

    with st.form("add_operator", clear_on_submit=True):
        new_operator = st.text_input("Nuovo operatore")
        add_operator = st.form_submit_button("Aggiungi operatore", type="primary", use_container_width=True)
    if add_operator:
        name = upper(new_operator)
        if not name:
            st.error("Inserisci il nome dell’operatore.")
        else:
            with db() as conn:
                conn.execute(
                    "INSERT INTO operator_config (name, active) VALUES (?, 1) "
                    "ON CONFLICT(name) DO UPDATE SET active = 1",
                    (name,),
                )
            st.success(f"Operatore {name} disponibile nel modulo.")
            st.rerun()

    rows = configured_operators(active_only=False)
    if not rows:
        st.info("Nessun operatore configurato.")
        return

    st.subheader("Operatori configurati")
    st.dataframe(
        pd.DataFrame(rows).rename(columns={"name": "Operatore", "active": "Attivo"}),
        use_container_width=True,
        hide_index=True,
        column_config={"Attivo": st.column_config.CheckboxColumn()},
    )
    selected_name = st.selectbox("Operatore da gestire", [row["name"] for row in rows])
    selected_row = next(row for row in rows if row["name"] == selected_name)
    c1, c2 = st.columns(2)
    renamed = c1.text_input("Nuovo nome", value=selected_name, key=f"rename_{selected_name}")
    active = c2.checkbox("Attivo nella tendina", value=bool(selected_row["active"]), key=f"active_{selected_name}")
    if st.button("Salva modifiche operatore", type="primary", use_container_width=True):
        new_name = upper(renamed)
        if not new_name:
            st.error("Il nome non può essere vuoto.")
        else:
            try:
                with db() as conn:
                    conn.execute(
                        "UPDATE operator_config SET name = ?, active = ? WHERE name = ?",
                        (new_name, int(active), selected_name),
                    )
                    if new_name != selected_name:
                        conn.execute("UPDATE rentals SET operator = ? WHERE UPPER(TRIM(operator)) = ?", (new_name, selected_name))
                        conn.execute("UPDATE contracts SET operator = ? WHERE UPPER(TRIM(operator)) = ?", (new_name, selected_name))
                        conn.execute("UPDATE damage_charges SET operator = ? WHERE UPPER(TRIM(operator)) = ?", (new_name, selected_name))
                st.success("Operatore aggiornato.")
                st.rerun()
            except sqlite3.IntegrityError:
                st.error("Esiste già un operatore con questo nome.")

    confirm_delete = st.checkbox("Confermo la rimozione dalla configurazione")
    if st.button("Elimina operatore", disabled=not confirm_delete, use_container_width=True):
        with db() as conn:
            conn.execute("DELETE FROM operator_config WHERE name = ?", (selected_name,))
        st.success("Operatore rimosso dalla tendina. I dati storici restano invariati.")
        st.rerun()


def user_settings():
    st.header("Utenti e autorizzazioni")
    if not user_is_admin():
        st.error("Questa funzione è riservata agli amministratori.")
        return

    st.caption("Crea gli accessi personali, collega l’operatore e scegli le aree visibili nel menu.")
    operator_names = [row["name"] for row in configured_operators()]

    with st.expander("Crea un nuovo utente", expanded=True):
        with st.form("create_app_user", clear_on_submit=True):
            c1, c2 = st.columns(2)
            username = c1.text_input("Username *")
            display_name = c2.text_input("Nome visualizzato *")
            c3, c4 = st.columns(2)
            password = c3.text_input("Password iniziale *", type="password")
            operator_name = c4.selectbox("Operatore collegato", [""] + operator_names)
            permissions = st.multiselect("Aree autorizzate *", PERMISSION_AREAS)
            is_admin = st.checkbox("Amministratore: accesso completo e gestione utenti")
            submitted = st.form_submit_button("Crea utente", type="primary", use_container_width=True)
        if submitted:
            normalized_username = clean(username).lower()
            if not normalized_username or not display_name:
                st.error("Inserisci username e nome visualizzato.")
            elif len(password) < 8:
                st.error("La password deve contenere almeno 8 caratteri.")
            elif not is_admin and not permissions:
                st.error("Seleziona almeno un’area autorizzata.")
            else:
                try:
                    with db() as conn:
                        conn.execute(
                            """
                            INSERT INTO app_users
                            (username, password_hash, display_name, operator_name, permissions, active, is_admin, created_at)
                            VALUES (?, ?, ?, ?, ?, 1, ?, ?)
                            """,
                            (
                                normalized_username, password_hash(password), clean(display_name),
                                upper(operator_name), json.dumps(permissions), int(is_admin),
                                datetime.now().isoformat(timespec="seconds"),
                            ),
                        )
                    st.success(f"Utente {normalized_username} creato.")
                    st.rerun()
                except sqlite3.IntegrityError:
                    st.error("Questo username esiste già.")

    with db() as conn:
        users = [dict(row) for row in conn.execute("SELECT * FROM app_users ORDER BY username").fetchall()]
    if not users:
        st.info("Non sono ancora presenti utenti personali. L’accesso admin configurato nei Secrets resta attivo.")
        return

    summary = pd.DataFrame([
        {
            "Username": row["username"], "Nome": row["display_name"],
            "Operatore": row["operator_name"], "Aree": " · ".join(json.loads(row["permissions"] or "[]")),
            "Amministratore": bool(row["is_admin"]), "Attivo": bool(row["active"]),
        }
        for row in users
    ])
    st.subheader("Utenti configurati")
    st.dataframe(summary, use_container_width=True, hide_index=True)

    selected_username = st.selectbox("Utente da modificare", [row["username"] for row in users])
    selected = next(row for row in users if row["username"] == selected_username)
    selected_permissions = json.loads(selected["permissions"] or "[]")
    with st.form(f"edit_user_{selected_username}"):
        c1, c2 = st.columns(2)
        edited_name = c1.text_input("Nome visualizzato", value=selected["display_name"] or "")
        existing_operator = upper(selected["operator_name"])
        edit_operator_options = [""] + operator_names
        if existing_operator and existing_operator not in edit_operator_options:
            edit_operator_options.append(existing_operator)
        edited_operator = c2.selectbox(
            "Operatore collegato", edit_operator_options,
            index=edit_operator_options.index(existing_operator) if existing_operator in edit_operator_options else 0,
        )
        edited_permissions = st.multiselect("Aree autorizzate", PERMISSION_AREAS, default=selected_permissions)
        c3, c4 = st.columns(2)
        edited_admin = c3.checkbox("Amministratore", value=bool(selected["is_admin"]))
        edited_active = c4.checkbox("Utente attivo", value=bool(selected["active"]))
        new_password = st.text_input("Nuova password (lascia vuoto per non cambiarla)", type="password")
        save_user = st.form_submit_button("Salva modifiche", type="primary", use_container_width=True)
    if save_user:
        if not edited_name:
            st.error("Il nome visualizzato è obbligatorio.")
        elif new_password and len(new_password) < 8:
            st.error("La nuova password deve contenere almeno 8 caratteri.")
        elif not edited_admin and not edited_permissions:
            st.error("Seleziona almeno un’area autorizzata.")
        else:
            with db() as conn:
                conn.execute(
                    """
                    UPDATE app_users SET display_name = ?, operator_name = ?, permissions = ?,
                    active = ?, is_admin = ? WHERE username = ?
                    """,
                    (
                        clean(edited_name), upper(edited_operator), json.dumps(edited_permissions),
                        int(edited_active), int(edited_admin), selected_username,
                    ),
                )
                if new_password:
                    conn.execute(
                        "UPDATE app_users SET password_hash = ? WHERE username = ?",
                        (password_hash(new_password), selected_username),
                    )
            st.success("Utente aggiornato.")
            st.rerun()

    confirm_delete = st.checkbox(f"Confermo l’eliminazione dell’utente {selected_username}")
    if st.button("Elimina utente", disabled=not confirm_delete, use_container_width=True):
        with db() as conn:
            conn.execute("DELETE FROM app_users WHERE username = ?", (selected_username,))
        st.success("Utente eliminato.")
        st.rerun()


def login():
    configured = str(st.secrets.get("ADMIN_PASSWORD", "") or "").strip()
    if st.session_state.get("authenticated"):
        if "current_user" not in st.session_state:
            st.session_state["current_user"] = {
                "username": "admin", "display_name": "Amministratore", "operator_name": "",
                "permissions": PERMISSION_AREAS, "is_admin": True,
            }
        return True
    st.title("Gestionale Ancillary")
    username = st.text_input("Username", value="admin")
    password = st.text_input("Password", type="password")
    if st.button("Accedi", type="primary", use_container_width=True):
        normalized_username = clean(username).lower()
        if normalized_username == "admin" and configured and hmac.compare_digest(password, configured):
            st.session_state["authenticated"] = True
            st.session_state["current_user"] = {
                "username": "admin", "display_name": "Amministratore", "operator_name": "",
                "permissions": PERMISSION_AREAS, "is_admin": True,
            }
            st.rerun()
        with db() as conn:
            row = conn.execute(
                "SELECT * FROM app_users WHERE username = ? AND active = 1", (normalized_username,)
            ).fetchone()
        if row and password_matches(password, row["password_hash"]):
            st.session_state["authenticated"] = True
            st.session_state["current_user"] = {
                "username": row["username"], "display_name": row["display_name"],
                "operator_name": row["operator_name"],
                "permissions": json.loads(row["permissions"] or "[]"), "is_admin": bool(row["is_admin"]),
            }
            st.rerun()
        st.error("Username o password errati.")
    if not configured:
        with db() as conn:
            user_count = conn.execute("SELECT COUNT(*) FROM app_users WHERE active = 1").fetchone()[0]
        if user_count == 0:
            st.warning("Configura ADMIN_PASSWORD nei Secrets per attivare il primo accesso amministratore.")
    return False


